package cl.bolsillo.app;
import org.json.*;import java.time.*;import java.util.*;
/** The pictured totals and the opened records must be exactly the same ledger view. */
public final class ChartUpgradeTest {
 static int checks;static void yes(boolean value,String text){checks++;if(!value)throw new AssertionError(text);}
 static JSONObject tx(String id,String category,String account,long value,String date)throws Exception{return new JSONObject().put("id",id).put("type","expense").put("status","posted").put("amount",value).put("date",date).put("category",category).put("account",account).put("note",id);}
 static long sum(List<JSONObject> rows)throws Exception{long total=0;for(JSONObject t:rows)total=Math.addExact(total,Finance.personalExpense(t));return total;}
 static void checkSnapshot(SpendingCharts.Snapshot snap)throws Exception{long total=0;Set<String> seen=new HashSet<>();for(SpendingCharts.Slice slice:snap.slices){List<JSONObject> rows=snap.records(slice);yes(sum(rows)==slice.value,"slice opens exactly its own personal amount: "+slice.label);total=Math.addExact(total,slice.value);for(JSONObject tx:rows)yes(seen.add(tx.getString("id")),"a record belongs to only one slice");}yes(total==snap.total&&sum(snap.records(null))==snap.total,"chart and all-records totals agree exactly");yes(seen.size()==snap.rows.size(),"every included record remains reachable");}
 public static void main(String[] args)throws Exception{
  JSONObject data=Ledger.initial();String month=Ledger.today().substring(0,7),today=Ledger.today();LocalDate first=LocalDate.parse(month+"-01");JSONArray records=data.getJSONArray("transactions");
  Ledger.find(data.getJSONArray("categories"),"expense-0").put("name","Servicios");Ledger.find(data.getJSONArray("categories"),"expense-7").put("name","Servicios");
  records.put(tx("shared","expense-7","bank-mach",9990,today).put("shares",new JSONArray().put(new JSONObject().put("id","family").put("amount",5000))));records.put(tx("transport","expense-1","bank-bancoestado",21200,today));
  records.put(tx("previous","expense-0","bank-mach",30000,first.minusMonths(1).toString()));records.put(tx("prior-two","expense-3","bank-mach",40000,first.minusMonths(2).toString()));records.put(tx("too-old","expense-0","bank-mach",88888,first.minusMonths(3).toString()));
  records.put(tx("future","expense-0","bank-mach",77777,first.plusMonths(1).toString()));records.put(tx("pending","expense-0","bank-mach",66666,today).put("status","pending"));records.put(tx("excluded","expense-0","bank-mach",55555,today).put("excluded",true));records.put(tx("income","expense-0","bank-mach",44444,today).put("type","income"));records.put(tx("fully-shared","expense-7","bank-mach",1000,today).put("shares",new JSONArray().put(new JSONObject().put("id","other").put("amount",1000))));
  String before=data.toString();SpendingCharts.Snapshot current=SpendingCharts.snapshot(data,0,month),quarter=SpendingCharts.snapshot(data,1,month),account=SpendingCharts.snapshot(data,2,month);
  yes(current.total==26190&&current.rows.size()==2,"current month excludes others' shares and non-expenses");yes(quarter.total==96190&&quarter.rows.size()==4,"quarter is three exact calendar months, not all history");yes(account.total==current.total&&account.slices.size()==2,"account and category views use identical spending");yes(quarter.from.equals(first.minusMonths(2).toString())&&quarter.until.equals(today),"displayed quarter dates match actual query boundaries");
  checkSnapshot(current);checkSnapshot(quarter);checkSnapshot(account);
  SpendingCharts.Slice subscription=quarter.slices.stream().filter(s->s.id.equals("expense-7")).findFirst().get();yes(quarter.records(subscription).size()==1&&quarter.records(subscription).get(0).getString("id").equals("shared"),"identical category labels never mix different IDs");
  SpendingCharts.Snapshot old=SpendingCharts.snapshot(data,0,first.minusMonths(1).toString().substring(0,7));yes(old.total==30000&&old.rows.size()==1,"historical month does not silently open current-month transactions");yes(old.until.equals(first.minusDays(1).toString()),"historical month ends at its actual final date");checkSnapshot(old);
  SpendingCharts.Snapshot future=SpendingCharts.snapshot(data,0,first.plusMonths(1).toString().substring(0,7));yes(future.total==0&&future.rows.isEmpty(),"future dated records cannot become observed spending");
  yes(before.equals(data.toString()),"all snapshots and drilldowns leave complete financial JSON untouched");
  boolean immutable=false;try{current.slices.clear();}catch(UnsupportedOperationException expected){immutable=true;}yes(immutable,"snapshot category list is immutable");immutable=false;try{current.slices.get(0).members.add("extra");}catch(UnsupportedOperationException expected){immutable=true;}yes(immutable,"Other membership cannot be changed by the UI");
  JSONObject many=Ledger.initial();JSONArray tx=many.getJSONArray("transactions");for(int i=0;i<8;i++)tx.put(tx("large-"+i,"expense-"+i,"bank-mach",1000000000000L-i*1000000,today));tx.put(tx("unassigned","","bank-mach",10,today));String original=many.toString();SpendingCharts.Snapshot grouped=SpendingCharts.snapshot(many,0,month);yes(grouped.slices.size()==5&&grouped.slices.get(4).label.equals("Otros"),"small categories form one usable remainder");SpendingCharts.Slice remainder=grouped.slices.get(4);yes(remainder.members.size()==5&&remainder.members.contains(""),"Other keeps exact IDs including an unassigned category");yes(grouped.records(remainder).size()==5,"Other opens only its grouped records, never all categories");checkSnapshot(grouped);yes(original.equals(many.toString()),"grouping large CLP amounts is strictly read-only");
  JSONObject overlap=Ledger.initial();Ledger.find(overlap.getJSONArray("categories"),"expense-0").put("name","Otros");for(int i=0;i<7;i++)overlap.getJSONArray("transactions").put(tx("same-label-"+i,"expense-"+i,"bank-mach",10000-i*1000,today));SpendingCharts.Snapshot separated=SpendingCharts.snapshot(overlap,0,month);yes(separated.slices.get(0).label.equals("Otros")&&separated.slices.get(4).label.equals("Más categorías"),"a real Otros category stays distinct from the grouped remainder");checkSnapshot(separated);
  yes(SpendingCharts.percent(1,10000).equals("<1%"),"small positive spending is never labelled zero");yes(SpendingCharts.percent(50,100).equals("50%"),"exact percentages remain ordinary percentages");yes(SpendingCharts.snapshot(Ledger.initial(),0,month).total==0,"empty chart contains no placeholder expenses");
  boolean badMode=false;try{SpendingCharts.snapshot(data,99,month);}catch(IllegalArgumentException expected){badMode=true;}yes(badMode,"unknown chart mode cannot produce an incoherent detail");
  System.out.println("PASS: "+checks+" chart periods, exact drilldown IDs, shared spending and large-money preservation checks");
 }
}
